192	          filter: new TimelineFilter.All(),
193	          internalIdPrefix: undefined,
194	          dateDividerMode: DateDividerMode.Daily,
195	          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
196	          reportUtds: false,
197	        });
