203	        // cached diffs (from SQLite) are received immediately — no network needed.
204	        // Set up timeline listener for real-time updates
205	        timelineListenerHandle = await timeline.addListener({
206	          onUpdate: (diffs) => {
207	            const beforeCount = timelineItemsRef.current.length;
208	            diffs.forEach((diff) => {
209	              const change = diff.tag;
210	              const timelineItems = timelineItemsRef.current;
211	              switch (change) {
212	                case TimelineDiff_Tags.Append: {
213	                  if (diff.inner.values.length > 0) {
214	                    timelineItems.push(...diff.inner.values.map(toEventItem));
215	                  }
216	                  break;
217	                }
218	                case TimelineDiff_Tags.Insert: {
219	                  const { index, value } = diff.inner;
220	                  timelineItems.splice(index, 0, toEventItem(value));
221	                  break;
222	                }
223	                case TimelineDiff_Tags.Set: {
224	                  const { index, value } = diff.inner;
225	                  const ev = toEventItem(value);
226	                  const oldItem = timelineItems[index];
227	                  const oldTxId = oldItem ? getTransactionId(oldItem) : null;
228	
229	                  timelineItems[index] = ev;
230	
231	                  // Detect txId→eventId transition: old item was a local echo, new item is confirmed.
232	                  // Use the specific txId from the replaced item (not FIFO shift) so out-of-order
233	                  // confirmations don't mismatch queue entries.
234	                  if (oldTxId && ev && !getTransactionId(ev)) {
235	                    const queueIdx = pendingTransactionIdsQueue.current.indexOf(oldTxId);
236	                    if (queueIdx !== -1) {
237	                      pendingTransactionIdsQueue.current.splice(queueIdx, 1);
238	                    }
239	                    // Remove any stale duplicate local echo still present elsewhere in the list.
240	                    const dupeIdx = timelineItems.findIndex((item, i) => {
241	                      if (i === index || !item) return false;
242	                      return getItemUniqueKey(item) === oldTxId;
243	                    });
244	                    if (dupeIdx !== -1) {
245	                      timelineItems.splice(dupeIdx, 1);
246	                    }
247	                  }
248	                  break;
249	                }
250	                case TimelineDiff_Tags.Remove: {
251	                  const { index: removeIndex } = diff.inner;
252	                  if (removeIndex >= 0 && removeIndex < timelineItems.length) {
253	                    timelineItems.splice(removeIndex, 1);
254	                  }
255	                  break;
256	                }
257	                case TimelineDiff_Tags.PushFront: {
258	                  const { value } = diff.inner;
259	                  timelineItems.unshift(toEventItem(value));
260	                  break;
261	                }
262	                case TimelineDiff_Tags.PushBack: {
263	                  const { value } = diff.inner;
264	                  const ev = toEventItem(value);
265	                  timelineItems.push(ev);
266	                  if (ev) {
267	                    const txId = getTransactionId(ev);
268	                    if (txId) {
269	                      pendingTransactionIdsQueue.current.push(txId);
270	                    }
271	                  }
272	                  break;
273	                }
274	                case TimelineDiff_Tags.PopFront: {
275	                  timelineItems.shift();
276	                  break;
277	                }
278	                case TimelineDiff_Tags.PopBack: {
279	                  timelineItems.pop();
280	                  break;
281	                }
282	                case TimelineDiff_Tags.Reset: {
283	                  const resetItems = diff.inner.values;
284	                  pendingTransactionIdsQueue.current = [];
285	                  timelineItemsRef.current = resetItems.map(toEventItem);
286	
287	                  const eventItems = timelineItemsRef.current.filter(
288	                    (i): i is EventTimelineItem => !!i,
289	                  );
290	                  pendingTransactionIdsQueue.current = eventItems
291	                    .map(getTransactionId)
292	                    .filter((id): id is string => !!id);
293	                  break;
294	                }
295	                case TimelineDiff_Tags.Truncate: {
296	                  const { length: cut } = diff.inner;
297	                  timelineItems.length = cut;
298	                  break;
299	                }
300	                case TimelineDiff_Tags.Clear: {
301	                  timelineItemsRef.current = [];
302	                  pendingTransactionIdsQueue.current = [];
303	                  eventIdsRef.current = new Set();
304	                  setEvents([]);
305	                  break;
306	                }
307	                default:
308	                  console.log("Unknown timeline change type:", change);
309	              }
310	            });
311	
312	            if (diffs.some((diff) => diff.tag !== TimelineDiff_Tags.Clear)) {
313	              if (rebuildTimerRef.current) clearTimeout(rebuildTimerRef.current);
314	              rebuildTimerRef.current = setTimeout(
315	                rebuildEventsFromTimelineItems,
316	                0,
317	              );
318	            }
319	
320	            if (ENABLE_TIMELINE_DEBUG) {
321	              const afterCount = timelineItemsRef.current.length;
322	              const tags = diffs.map((d) => d.tag).join(", ");
323	              console.log(
324	                `[TimelineDebug][${roomId}] diffs=[${tags}] items ${beforeCount}->${afterCount}`,
325	              );
326	            }
327	
328	          },
329	        });
330	
331	        // Paginate after the listener is set up so events flow through it.
332	        // Don't await — cached messages are already visible; network results
333	        // will arrive as further diffs without blocking the UI.
334	        isPaginatingRef.current = true;
335	        timeline.paginateBackwards(TIMELINE_PAGE_SIZE).catch((error) => {
336	          if (isDisposed) return;
337	          console.warn("Failed to load initial messages:", error);
338	        }).finally(() => {
339	          isPaginatingRef.current = false;
340	        });
341	      } catch (error) {
342	        console.error("Failed to initialize room timeline:", error);
343	        offlineToastHelper("Failed to load the messages. Please try again.");
344	        NavigationContainerRef.goBack();
345	        return null;
346	      }
347	    };
348	
349	    initRoomTimeline();
350	
351	    return () => {
352	      isDisposed = true;
353	      timelineListenerHandle?.cancel?.();
354	      if (rebuildTimerRef.current) clearTimeout(rebuildTimerRef.current);
355	      timelineRef.current = null;
356	      timelineItemsRef.current = [];
357	      isPaginatingRef.current = false;
358	      reachedStartRef.current = false;
359	    };
360	  }, [rebuildEventsFromTimelineItems, room, roomId]);
361	
362	  useEffect(() => {
363	    markAsRead().catch(console.error);
364	    room?.isDirect().then(setIsDirect).catch(console.error);
365	  }, [room, markAsRead]);
366	
367	  return {
368	    events,
369	    timelineRef,
370	    isPaginatingRef,
371	    reachedStartRef,
372	    isDirect,
373	    loadMoreMessages,
374	    markAsRead,
375	  };
376	};
